const input = $json.body ?? $json;

const name = String(input.name ?? '').trim();
const email = String(input.email ?? '').trim();
const subject = String(input.subject ?? '').trim();
const message = String(input.message ?? '').trim();

if (!name) {
  throw new Error('Customer name is required');
}

if (!email) {
  throw new Error('Customer email is required');
}

// More flexible email validation
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!emailRegex.test(email)) {
  throw new Error(`Invalid customer email address: ${email}`);
}

if (!subject) {
  throw new Error('Ticket subject is required');
}

if (!message) {
  throw new Error('Support message is required');
}

return [
  {
    json: {
      ticket_id: `TKT-${Date.now().toString().slice(-8)}`,
      name,
      email,
      subject,
      message,
      received_at: new Date().toISOString()
    }
  }
];

