const original = $('Validate & Prepare Ticket').first().json;
const raw = $json.choices?.[0]?.message?.content;

if (!raw) {
  throw new Error('Groq returned no AI response');
}

let ai;

try {
  ai = JSON.parse(raw);
} catch (error) {
  throw new Error('Groq returned invalid JSON: ' + raw);
}

const categories = ['Billing','Technical','Account','Refund','Order','Delivery','Security','General','Other'];
const priorities = ['Low','Medium','High','Critical'];
const sentiments = ['Positive','Neutral','Negative','Urgent'];

if (!categories.includes(ai.ticket_category)) ai.ticket_category = 'Other';
if (!priorities.includes(ai.priority)) ai.priority = 'Medium';
if (!sentiments.includes(ai.sentiment)) ai.sentiment = 'Neutral';

ai.confidence = Math.max(0, Math.min(100, Number(ai.confidence) || 0));
ai.needs_human_review = Boolean(ai.needs_human_review);

const auto_response_allowed =
  ai.confidence >= 85 &&
  ai.needs_human_review === false &&
  ai.priority !== 'Critical';

return [{
  json: {
    ...original,
    ...ai,
    auto_response_allowed,
    processed_at: new Date().toISOString()
  }
}];

const data = $('Parse & Validate AI Result').first().json;

return [{
  json: {
    success: true,
    status: 'auto_responded',
    email_sent: true,
    ticket: data
  }
}];

const data = $('Parse & Validate AI Result').first().json;

return [{
  json: {
    success: true,
    status: 'human_review_required',
    email_sent: false,
    message: 'Ticket analyzed successfully. A support agent must review the ticket before a customer response is sent.',
    ticket: data
  }
}];
